node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get products table schema
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name='products'\").get();
console.log('Schema:', schema.sql);
console.log();

// Search for the product
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4' OR name LIKE '%Aurora Smart Desk Lamp%'\").all();
console.log('Product:', JSON.stringify(product, null, 2));
"
